; Butterflies
; $7245-$7292

; Handler of the butterflies $30-$33. Explodes to diamonds next to Rockford or amoeba. Else it turns right, moves ahead or turns left.
handle_butterfly
        jsr check_enemy_touch
        bne butterfly_move
; not executed $724a-$7253
        lda #$21                        ; Explosion to diamonds: stages $20-$24.
        sta explosion_code
        jsr explode_here
        jmp scan_cell_settle
butterfly_move
        ldy #$29
        lda (cell_ptr),y
        and #$03
        tax
        ldy dir_offsets,x               ; Bits 0-1 index the cell on the right side of the butterfly.
        lda (cell_ptr),y
        bne butterfly_try_ahead
        clc
        txa
        adc #$01
        and #$03
        adc #$34                        ; Code $34-$37: butterfly already scanned in this frame.
        jsr set_cell
        jmp clear_cell_and_next
butterfly_try_ahead
        ldy dir_offsets_turned,x
        lda (cell_ptr),y
        bne butterfly_turn_left
        clc
        txa
        adc #$34
        ldy dir_offsets_turned,x
        jsr set_cell
        jmp clear_cell_and_next
butterfly_turn_left
        clc
        ldy #$29
        txa
        adc #$03
        and #$03
        adc #$34
        sta (cell_ptr),y
        jmp scan_cell_settle
